CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Languages" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NOT NULL,
    "Name" text NOT NULL,
    CONSTRAINT "PK_Languages" PRIMARY KEY ("Id")
);

CREATE TABLE "Municipalities" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    CONSTRAINT "PK_Municipalities" PRIMARY KEY ("Id")
);

CREATE TABLE "WasteCollectionSites" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MunicipalityId" integer NOT NULL,
    CONSTRAINT "PK_WasteCollectionSites" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_WasteCollectionSites_Municipalities_MunicipalityId" FOREIGN KEY ("MunicipalityId") REFERENCES "Municipalities" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Employees" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FullName" text NOT NULL,
    "SiteId" integer NOT NULL,
    CONSTRAINT "PK_Employees" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Employees_WasteCollectionSites_SiteId" FOREIGN KEY ("SiteId") REFERENCES "WasteCollectionSites" ("Id") ON DELETE CASCADE
);

CREATE TABLE "SiteTranslations" (
    "SiteId" integer NOT NULL,
    "LanguageId" integer NOT NULL,
    "Name" text NOT NULL,
    CONSTRAINT "PK_SiteTranslations" PRIMARY KEY ("SiteId", "LanguageId"),
    CONSTRAINT "FK_SiteTranslations_Languages_LanguageId" FOREIGN KEY ("LanguageId") REFERENCES "Languages" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_SiteTranslations_WasteCollectionSites_SiteId" FOREIGN KEY ("SiteId") REFERENCES "WasteCollectionSites" ("Id") ON DELETE CASCADE
);

